{#
/**
 * @file
 * Default theme implementation for a storage type option form element.
 *
 * Available variables:
 * - attributes: HTML attributes for the containing element.
 * - errors: (optional) Any errors for this form element, may not be set.
 * - label: A rendered label element.
 * - description: (optional) A list of description properties containing:
 *    - content: A description of the form element, may not be set.
 *    - attributes: (optional) A list of HTML attributes to apply to the
 *      description content wrapper. Will only be set when description is set.
 * - variant: specifies option type. Typically 'field-option' or 'field-suboption'.
 *
 * @see\Drupal\Core\Form\FormPreprocess::preprocessFormElement()
 *
 * @ingroup themeable
 */
#}
{%
  set classes = [
    errors ? 'form-item--error',
    variant ? variant ~ '__item'
  ]
%}
<div{{ attributes.addClass(classes) }}>
  {% if variant == 'field-option' %}
    {{ label }}
    <div{{ description.attributes }}>
      {{ description.content }}
    </div>
  {% endif %}
  {{ children }}
  {% if variant == 'field-suboption' %}
    {{ label }}
    <div{{ description.attributes.addClass(description_classes) }}>
      {{ description.content }}
    </div>
  {% endif %}
  {% if errors %}
    <div class="form-item--error-message">
      {{ errors }}
    </div>
  {% endif %}
</div>

{#
/**
 * @file
 * Theme override to display a single page.
 *
 * The doctype, html, head and body tags are not in this template. Instead they
 * can be found in the html.html.twig template in this directory.
 *
 * Available variables:
 *
 * General utility variables:
 * - base_path: The base URL path of the Drupal installation. Will usually be
 *   "/" unless you have installed Drupal in a sub-directory.
 * - is_front: A flag indicating if the current page is the front page.
 * - logged_in: A flag indicating if the user is registered and signed in.
 * - is_admin: A flag indicating if the user has permission to access
 *   administration pages.
 *
 * Site identity:
 * - front_page: The URL of the front page. Use this instead of base_path when
 *   linking to the front page. This includes the language domain or prefix.
 *
 * Page content (in order of occurrence in the default page.html.twig):
 * - node: Fully loaded node, if there is an automatically-loaded node
 *   associated with the page and the node ID is the second argument in the
 *   page's path (e.g. node/12345 and node/12345/revisions, but not
 *   comment/reply/12345).
 *
 * Regions:
 * - page.header: Items for the header region.
 * - page.primary_menu: Items for the primary menu region.
 * - page.secondary_menu: Items for the secondary menu region.
 * - page.highlighted: Items for the highlighted content region.
 * - page.help: Dynamic help text, mostly for admin pages.
 * - page.content: The main content of the current page.
 * - page.sidebar_first: Items for the first sidebar.
 * - page.sidebar_second: Items for the second sidebar.
 * - page.footer: Items for the footer region.
 * - page.breadcrumb: Items for the breadcrumb region.
 *
 * @see \Drupal\Core\Theme\ThemePreprocess::preprocessPage()
 * @see html.html.twig
 */
#}
<div class="layout-container">

  {% if page.pre_header|render|trim is not empty or
     page.header|render|trim is not empty %}
    <header class="layout-header" role="banner">
      <div class="container">
        {% if page.pre_header|render|trim is not empty %}
          {{ page.pre_header }}
        {% endif %}
        {% if page.header|render|trim is not empty %}
          {{ page.header }}
        {% endif %}
      </div>
    </header>
  {% endif %}

  <main>

    {% if page.highlighted %}
      <div class="layout-highlighted">
        <div class="container">
          {{ page.highlighted }}
        </div>
      </div>
    {% endif %}

    {% if page.tabs %}
    <div class="layout-tabs">
      <div class="container">
        {{ page.tabs }}
      </div>
    </div>
    {% endif %}

    {% if page.banner_top|render|trim is not empty %}
      <div class="layout-banner-top">
        {{ page.banner_top }}
      </div>
    {% endif %}

    {% if page.breadcrumbs|render|trim is not empty %}
    <div class="layout-breadcrumbs">
      <div class="container">
        {{ page.breadcrumbs }}
      </div>
    </div>
    {% endif %}

    {% if not node %}
      {% if page.page_title|render|trim is not empty %}
        <div class="layout-page-title">
          {% if is_front %}
            <div class="is-front container">
              {{ page.page_title }}
            </div>
            {% else %}
            <div class="container">
              {{ page.page_title }}
            </div>
          {% endif %}
        </div>
      {% endif %}
    {% endif %}

    <div class="main-content-area container">
      <div class="layout-content">
        <a id="main-content" tabindex="-1"></a>{# link is in html.html.twig #}
        {{ page.content }}
      </div>{# /.layout-content #}

      {% if page.sidebar|render|trim is not empty %}
        <aside class="layout-sidebar" role="complementary">
          {{ page.sidebar }}
        </aside>
      {% endif %}
    </div>

    {% if page.content_bottom|render|trim is not empty %}
      <div class="layout-content-bottom">
        {{ page.content_bottom }}
      </div>
    {% endif %}
  </main>

  <footer class="footer" role="contentinfo">
    {% if page.footer|render|trim is not empty %}
    <div class="layout-footer">
      <div class="container">
        {{ page.footer }}
      </div>
    </div>
    {% endif %}

    {% if page.bottom|render|trim is not empty %}
      <div class="layout-bottom">
        <div class="container">
          {{ page.bottom }}
        </div>
      </div>
    {% endif %}
  </footer>

</div>{# /.layout-container #}

{#
/**
 * @file
 * Theme override for a details element.
 *
 * This variation is used for theming the details of a Vertical Tabs element.
 *
 * Available variables
 * - attributes: A list of HTML attributes for the details element.
 * - errors: (optional) Any errors for this details element, may not be set.
 * - title: (optional) The title of the element, may not be set.
 * - description: (optional) The description of the element, may not be set.
 * - children: (optional) The children of the element, may not be set.
 * - value: (optional) The value of the element, may not be set.
 * - accordion: whether the details element should look as an accordion.
 * - accordion_item: whether the details element is an item of an accordion
 *   list.
 *
 * @see\Drupal\Core\Form\FormPreprocess::preprocessDetails()
 * @see claro_preprocess_details()
 */
#}
{%
  set classes = [
    'claro-details',
    'claro-details--vertical-tabs-item',
  ]
%}
{%
  set content_wrapper_classes = [
    'claro-details__wrapper',
    'details-wrapper',
    'claro-details__wrapper--vertical-tabs-item',
  ]
%}
{%
  set inner_wrapper_classes = [
    'claro-details__content',
    'claro-details__content--vertical-tabs-item',
  ]
%}
<details{{ attributes.addClass(classes) }}>
  {%- if title -%}
    {%
      set summary_classes = [
        'claro-details__summary',
        'claro-details__summary--vertical-tabs-item',
        required ? 'js-form-required',
        required ? 'form-required',
      ]
    %}
    <summary{{ summary_attributes.addClass(summary_classes) }}>
      {{- title -}}
    </summary>
  {%- endif -%}
  <div{{ content_attributes.addClass(content_wrapper_classes) }}>
    <div{{ create_attribute({class: inner_wrapper_classes}) }}>
      {% if errors %}
        <div class="form-item form-item__error-message">
          {{ errors }}
        </div>
      {% endif %}
      {%- if description -%}
        <div class="claro-details__description">{{ description }}</div>
      {%- endif -%}
      {%- if children -%}
        {{ children }}
      {%- endif -%}
      {%- if value -%}
        {{ value }}
      {%- endif -%}
    </div>
  </div>
</details>

